const Database = require('/tmp/node_modules/better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

const reminderId = crypto.randomUUID();
const content = 'Aurora Smart Desk Lamp Pro (PROD-73FAB4) — Price: \$88 | In Stock (24 units) | 12-month warranty | 30-day return window (0% restocking fee). Brand: Aurora Home. Features: 12W LED, adjustable color temp (2700K–6500K), dimming, app control, USB-C charging port, and ambient presets.';
const creationTimestamp = 1788228000;  // consistent with existing entries
const reminderTimestamp = 1788314400;  // ~1 day later
const createdAt = '2026-09-01T10:00:00';

db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, NULL, NULL, ?)').run(
  reminderId, content, creationTimestamp, reminderTimestamp, createdAt
);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Inserted reminder:', JSON.stringify(row, null, 2));
"
